using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.Build.Reporting;
using HarborValePreviewReview.Editor;
namespace ClaudeSFX.Editor {
public static class SFXBuild {
 public const string Scene="Assets/ClaudeSFX/Scenes/SFXDemo.unity";
 public static void Build(){Directory.CreateDirectory("Verification/SFX");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Conditional effects | no physics");var controller=root.AddComponent<SFXDemoController>();controller.sound=new GameObject("Native procedural DSP mix").AddComponent<ProceduralEngineAudio>();controller.cars=new GameObject[2];controller.effects=new AnimatedCarController[2];var finch=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab");
  for(int i=0;i<2;i++){var car=UnityEngine.Object.Instantiate(finch);car.name=i==0?"Aster Finch | static visual":"Aster Apex | true sports visual";if(i==1)ApexStaticVisual.MakeVisual(car);var script=car.GetComponent<HarborValeGreybox.StarterCarSpecification>();if(script!=null)UnityEngine.Object.DestroyImmediate(script);controller.cars[i]=car;var fx=car.AddComponent<AnimatedCarController>();controller.effects[i]=fx;fx.drift=car.AddComponent<DriftingSystem>();fx.drift.smoke=new[]{DriftingSystem.Make(car.transform,new Vector3(-.78f,.1f,-1.225f),"Left tire slip smoke"),DriftingSystem.Make(car.transform,new Vector3(.78f,.1f,-1.225f),"Right tire slip smoke")};fx.exhaust=DriftingSystem.Make(car.transform,new Vector3(.58f,.25f,-2.1f),"Exhaust effect");var stand=GameObject.CreatePrimitive(PrimitiveType.Cylinder);stand.name="Detached turbo rotor display | effects-only";stand.transform.position=new Vector3(2.1f,.8f,1);stand.transform.localScale=new Vector3(.3f,.08f,.3f);fx.turboRotor=stand.transform;stand.transform.SetParent(car.transform,true);}
  var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="Effects review floor";floor.transform.position=new Vector3(0,-.1f,0);floor.transform.localScale=new Vector3(18,.2f,18);floor.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Standard")){color=new Color(.16f,.19f,.23f)};
  var lamp=new GameObject("Preview key light").AddComponent<Light>();lamp.type=LightType.Directional;lamp.intensity=1.3f;lamp.transform.rotation=Quaternion.Euler(40,-30,0);RenderSettings.ambientLight=new Color(.6f,.65f,.72f);var cam=new GameObject("Main Camera");cam.tag="MainCamera";var camera=cam.AddComponent<Camera>();camera.backgroundColor=new Color(.07f,.1f,.15f);camera.clearFlags=CameraClearFlags.SolidColor;cam.transform.position=new Vector3(5.4f,3.1f,6);cam.transform.LookAt(new Vector3(0,.7f,0));cam.AddComponent<AudioListener>();new GameObject("SFX verification | opt-in").AddComponent<SFXReviewProbe>();controller.SelectCar(0);PreviewBake.Materials("Assets/ClaudeSFX/Generated");EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Scene);EditorSceneManager.OpenScene(Scene);if(UnityEngine.Object.FindObjectsByType<Rigidbody>(FindObjectsSortMode.None).Length!=0)throw new Exception("Unexpected preview physics");PlayerSettings.productName="HarborValeEffectsPreview";PlayerSettings.defaultScreenWidth=1280;PlayerSettings.defaultScreenHeight=800;PlayerSettings.fullScreenMode=FullScreenMode.Windowed;PlayerSettings.runInBackground=true;Directory.CreateDirectory("Verification/SFX/Windows");var b=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Scene},target=BuildTarget.StandaloneWindows64,locationPathName="Verification/SFX/Windows/EffectsPreview.exe",options=BuildOptions.Development});File.WriteAllText("Verification/SFX/build.txt",b.summary.result+" | errors "+b.summary.totalErrors);if(b.summary.result!=BuildResult.Succeeded)throw new Exception("Effects export failed");AssetDatabase.ExportPackage(new[]{"Assets/ClaudeSFX","Assets/Review/Scripts/PreviewRecorder.cs","Assets/Review/Editor/PreviewBake.cs","Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab"},"Verification/SFX/ReviewedEffects.unitypackage",ExportPackageOptions.Recurse|ExportPackageOptions.IncludeDependencies);}
